{
  "name": "Marconi 203N系列射频信号发生器",
  "name_en": "Marconi 203N Series RF Signal Generator",
  "manufacturer": "Marconi Instruments",
  "description": "Marconi 203N系列是一类台式射频/微波信号发生器，可在约10 kHz到1.35 GHz、2.7 GHz或5.4 GHz范围内输出可调频率与幅度的测试信号，并支持多种调制方式。该类仪器常用于射频电路、通信设备和微波实验中的信号注入、链路测试、接收机校准与一般电子测量。",
  "description_en": "The Marconi 203N series is a benchtop RF/microwave signal generator that provides adjustable-frequency, adjustable-amplitude test signals from about 10 kHz up to 1.35 GHz, 2.7 GHz, or 5.4 GHz depending on model, with support for multiple modulation modes. It is commonly used for signal injection, receiver calibration, communications testing, and general RF/microwave laboratory measurements.",
  "tag_hints": [
    "RF signal generator",
    "microwave source",
    "frequency synthesis",
    "AM/FM/pulse modulation",
    "receiver calibration",
    "communications testing"
  ],
  "actions": [
    {
      "action_name": "auto-frequency",
      "description": "获取或设置输出频率。",
      "description_en": "Get or set the output frequency."
    },
    {
      "action_name": "auto-amplitude",
      "description": "获取或设置输出幅度。",
      "description_en": "Get or set the output amplitude."
    },
    {
      "action_name": "auto-output",
      "description": "获取或设置射频输出开关状态。",
      "description_en": "Get or set the RF output on/off state."
    },
    {
      "action_name": "auto-modulation_disable",
      "description": "禁用指定的调制方式。",
      "description_en": "Disable the specified modulation mode."
    },
    {
      "action_name": "auto-modulation_enable",
      "description": "启用指定的调制方式。",
      "description_en": "Enable the specified modulation mode."
    },
    {
      "action_name": "auto-modulation_output",
      "description": "获取或设置调制输出状态。",
      "description_en": "Get or set the modulation output state."
    },
    {
      "action_name": "auto-modulation",
      "description": "获取或设置调制方式及相关参数。",
      "description_en": "Get or set the modulation mode and related parameters."
    },
    {
      "action_name": "auto-SystemErrorQueue",
      "description": "读取系统错误队列。",
      "description_en": "Read the system error queue."
    }
  ]
}

